import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJ0NkIPM.js";var i=JSON.parse(`{"title":"계획 뷰 - 랠리 포인트","description":"","frontmatter":{},"headers":[],"relativePath":"ko/qgc-user-guide/plan_view/plan_rally_points.md","filePath":"ko/qgc-user-guide/plan_view/plan_rally_points.md"}`),a={name:`ko/qgc-user-guide/plan_view/plan_rally_points.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="계획-뷰-랠리-포인트" tabindex="-1">계획 뷰 - 랠리 포인트 <a class="header-anchor" href="#계획-뷰-랠리-포인트" aria-label="Permalink to “계획 뷰 - 랠리 포인트”">​</a></h1><p>랠리 포인트는 대체 착륙 또는 배회 장소입니다. 일반적으로 리턴/RTL 모드에서 홈 위치보다 더 안전하거나 더 편리한(예: 더 가까운) 목적지를 지정합니다.</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p><em>QGroundControl</em> will not display the Rally Point options if they are not supported by the connected vehicle firmware.</p></div><h2 id="랠리-포인트-사용법" tabindex="-1">랠리 포인트 사용법 <a class="header-anchor" href="#랠리-포인트-사용법" aria-label="Permalink to “랠리 포인트 사용법”">​</a></h2><p>랠리 포인트를 생성하려면:</p><ol><li>계획 뷰로 이동합니다.</li><li>Select the <strong>Rally Points</strong> layer using the <a href="./plan_view.html#layer-switcher">Layer Switcher</a> in the top-right area of the map (or expand the <strong>Rally Points</strong> section in the <a href="./plan_view.html#plan-editor-panel">Plan Editor Panel</a>)</li><li>랠리 포인트를 지도에서 원하는 곳을 클릭합니다. <ul><li>각각에 대해 <strong>R</strong> 마커가 추가됩니다.</li><li>The currently active marker has a different color (green) and its editor is expanded in the <em>Rally Points</em> section.</li></ul></li><li>Make any rally point active by selecting it on the map or in the <em>Rally Points</em> section: <ul><li>Move the active rally point by either dragging it on the map or editing the position fields in its editor.</li><li>Delete a rally point by pressing the <strong>X</strong> delete button on its editor.</li></ul></li></ol><h2 id="랠리-포인트-업로드" tabindex="-1">랠리 포인트 업로드 <a class="header-anchor" href="#랠리-포인트-업로드" aria-label="Permalink to “랠리 포인트 업로드”">​</a></h2><p>Rally points are uploaded along with the rest of the plan using the <strong>Upload</strong> button in the <a href="./plan_view.html#file">Plan Toolbar</a>.</p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};